1	/**
2	 * Waitlist intelligence builder
3	 *
4	 * Pure aggregation over email_waitlist rows → one JSON payload the admin
5	 * dashboard renders. No DB access here so the logic is unit-testable; the
6	 * API route fetches rows and calls buildWaitlistIntel().
7	 *
8	 * Classification: every signup's email domain is bucketed as
9	 *   personal  — free/consumer providers (gmail, qq, outlook…) + known typos
10	 *   edu       — academic domains (.edu, .edu.xx, .ac.xx)
11	 *   corporate — everything else (company or custom domains)
12	 * Corporate domains with 2+ signups are "team clusters" — the strongest
13	 * adoption signal we have. KNOWN_COMPANIES adds display names for orgs
14	 * we've manually identified.
15	 */
16	
17	export interface WaitlistRow {
18	  id: number;
19	  email: string;
20	  source: string | null;
21	  note: string | null;
22	  createdAt: Date;
23	}
24	
25	export type DomainKind = 'corporate' | 'edu' | 'personal';
26	
27	export interface IntelEntry {
28	  email: string;
29	  source: string | null;
30	  note: string | null;
31	  createdAt: string;
32	}
33	
34	export interface IntelCompany {
35	  domain: string;
36	  kind: 'corporate' | 'edu';
37	  count: number;
38	  knownName: string | null;
39	  latestAt: string;
40	  entries: IntelEntry[];
41	}
42	
43	export interface IntelRecent extends IntelEntry {
44	  id: number;
45	  domainKind: DomainKind;
46	  knownName: string | null;
47	}
48	
49	export interface WaitlistIntel {
50	  generatedAt: string;
51	  totals: {
52	    all: number;
53	    lastHour: number;
54	    last24h: number;
55	    last7d: number;
56	    withNotes: number;
57	    corporate: number;
58	    corporatePct: number;
59	  };
60	  trend: Array<{ hourStart: string; count: number }>;
61	  sources: Array<{ source: string; count: number; last24h: number }>;
62	  companies: IntelCompany[];
63	  recent: IntelRecent[];
64	  notes: Array<IntelEntry & { knownName: string | null }>;
65	}
66	
67	/** Free/consumer email providers — never companies. */
68	const FREE_PROVIDERS = new Set([
69	  // Big global
70	  'gmail.com', 'googlemail.com', 'icloud.com', 'me.com', 'mac.com',
71	  'outlook.com', 'outlook.es', 'outlook.it', 'outlook.fr', 'outlook.de',
72	  'outlook.com.br', 'outlook.in', 'hotmail.com', 'hotmail.co.uk',
73	  'hotmail.fr', 'hotmail.de', 'hotmail.es', 'hotmail.it', 'live.com',
74	  'live.cn', 'live.co.uk', 'msn.com', 'yahoo.com', 'yahoo.co.uk',
75	  'yahoo.fr', 'yahoo.de', 'yahoo.es', 'yahoo.it', 'yahoo.com.br',
76	  'yahoo.co.in', 'yahoo.com.tw', 'ymail.com', 'rocketmail.com', 'aol.com',
77	  // Privacy / indie
78	  'proton.me', 'protonmail.com', 'pm.me', 'tutanota.com', 'tuta.io',
79	  'fastmail.com', 'hey.com', 'duck.com', 'duckduckgo.com', 'hushmail.com',
80	  'passmail.net', 'altmail.kr', 'mail.com', 'dr.com', 'gmx.com', 'gmx.de',
81	  'gmx.net', 'gmx.at', 'gmx.ch', 'zoho.com', 'zohomail.com',
82	  // China
83	  'qq.com', '163.com', '126.com', '139.com', 'foxmail.com', 'sina.com',
84	  'sina.cn', 'sohu.com', 'aliyun.com', 'yeah.net', '189.cn', '21cn.com',
85	  // Korea / Japan
86	  'naver.com', 'daum.net', 'hanmail.net', 'kakao.com', 'yahoo.co.jp',
87	  // Russia / Eastern Europe
88	  'mail.ru', 'yandex.ru', 'yandex.com', 'bk.ru', 'inbox.ru', 'list.ru',
89	  'rambler.ru', 'ukr.net', 'i.ua', 'tut.by', 'seznam.cz', 'wp.pl',
90	  'o2.pl', 'interia.pl', 'op.pl', 'abv.bg',
91	  // Telco / ISP
92	  'sbcglobal.net', 'att.net', 'verizon.net', 'comcast.net', 'cox.net',
93	  'charter.net', 'earthlink.net', 'bellsouth.net', 'shaw.ca', 'rogers.com',
94	  'sympatico.ca', 'btinternet.com', 'sky.com', 'talktalk.net',
95	  'virginmedia.com', 'orange.fr', 'wanadoo.fr', 'free.fr', 'sfr.fr',
96	  'laposte.net', 'libero.it', 'tiscali.it', 'telenet.be', 'ziggo.nl',
97	  'xs4all.nl', 't-online.de', 'web.de', 'freenet.de', 'arcor.de',
98	  'bluewin.ch', 'telia.com', 'mail.dk',
99	  // Test / placeholder
100	  'example.com',
101	]);
102	
103	/** Obvious typo'd free providers — a person, not an org. */
104	const TYPO_PROVIDERS = new Set([
105	  'gamil.com', 'gmial.com', 'gmal.com', 'gnail.com', 'gmaill.com',
106	  'gmnail.com', 'gmail.co', 'gmail.cm', 'gmail.con', 'gmail..com',
107	  'göail.com', 'gemail.com', 'gimail.com', 'hotmial.com', 'hotnail.com',
108	  'hotmal.com', 'outlok.com', 'outloook.com', 'yaho.com', 'yahooo.com',
109	  'iclod.com', 'icoud.com', 'icloud.con', '63.com', 'gamill.com',
110	]);
111	
112	/**
113	 * Orgs we've manually identified (domain → display name). Not exhaustive —
114	 * unknown corporate domains still surface, just without a friendly name.
115	 */
116	const KNOWN_COMPANIES: Record<string, string> = {
117	  'airbnb.com': 'Airbnb',
118	  'accenture.com': 'Accenture',
119	  'tencent.com': 'Tencent',
120	  'zillowgroup.com': 'Zillow Group',
121	  'checkpoint.com': 'Check Point',
122	  'digitalocean.com': 'DigitalOcean',
123	  'thetradedesk.com': 'The Trade Desk',
124	  'pony.ai': 'Pony.ai',
125	  'lixiang.com': 'Li Auto',
126	  'lotuscars.com.cn': 'Lotus Cars',
127	  'talkdesk.com': 'Talkdesk',
128	  'deputy.com': 'Deputy',
129	  'groww.in': 'Groww',
130	  'grofers.com': 'Blinkit (Grofers)',
131	  'zomato.com': 'Zomato',
132	  'fandango.com': 'Fandango',
133	  'exclusive-networks.com': 'Exclusive Networks',
134	  'ventionteams.com': 'Vention',
135	  'webpros.com': 'WebPros (cPanel/Plesk)',
136	  'simformsolutions.com': 'Simform',
137	  'nextlabs.com': 'NextLabs',
138	  'novibet.com': 'Novibet',
139	  'truecommerce.com': 'TrueCommerce',
140	  'myalfred.com': 'myAlfred (UAE super-app)',
141	  'chilipiper.com': 'Chili Piper',
142	  'aldar.com': 'Aldar Properties',
143	  'buk.cl': 'Buk',
144	  'aunalytics.com': 'Aunalytics',
145	  '3yourmind.com': '3YOURMIND',
146	  'kickdrumtech.com': 'Kickdrum',
147	  'dhc.com.cn': 'DHC Software',
148	  'wejungle.com': 'Jungle',
149	};
150	
151	/** Academic domains: .edu, or .edu.xx / .ac.xx ccTLD second-levels. */
152	const EDU_RE = /\.edu$|\.(edu|ac)\.[a-z]{2}$/;
153	
154	export function classifyDomain(domain: string): DomainKind {
155	  if (!domain) return 'personal'; // malformed email — a person, not an org
156	  if (FREE_PROVIDERS.has(domain) || TYPO_PROVIDERS.has(domain)) return 'personal';
157	  if (EDU_RE.test(domain)) return 'edu';
158	  return 'corporate';
159	}
160	
161	const HOUR_MS = 3_600_000;
162	const DAY_MS = 86_400_000;
163	const TREND_HOURS = 48;
164	const RECENT_LIMIT = 100;
165	
166	export function buildWaitlistIntel(rows: WaitlistRow[]): WaitlistIntel {
167	  const now = Date.now();
168	
169	  // Drop placeholder/test rows entirely.
170	  const real = rows.filter((r) => !r.email.toLowerCase().endsWith('@example.com'));
171	  // Newest first everywhere.
172	  real.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
173	
174	  const domainOf = (email: string) => (email.split('@')[1] ?? '').toLowerCase().trim();
175	  const hasNote = (r: WaitlistRow) => Boolean(r.note && r.note.trim());
176	
177	  // --- Totals -------------------------------------------------------------
178	  const inWindow = (ms: number) => real.filter((r) => now - r.createdAt.getTime() < ms).length;
179	  let corporateCount = 0;
180	  for (const r of real) {
181	    if (classifyDomain(domainOf(r.email)) === 'corporate') corporateCount += 1;
182	  }
183	
184	  // --- Hourly trend (last 48h, aligned to hour starts) ---------------------
185	  const trendStart = Math.floor(now / HOUR_MS) * HOUR_MS - (TREND_HOURS - 1) * HOUR_MS;
186	  const buckets = new Array<number>(TREND_HOURS).fill(0);
187	  for (const r of real) {
188	    const idx = Math.floor((r.createdAt.getTime() - trendStart) / HOUR_MS);
189	    if (idx >= 0 && idx < TREND_HOURS) buckets[idx] += 1;
190	  }
191	  const trend = buckets.map((count, i) => ({
192	    hourStart: new Date(trendStart + i * HOUR_MS).toISOString(),
193	    count,
194	  }));
195	
196	  // --- Sources --------------------------------------------------------------
197	  const sourceMap = new Map<string, { count: number; last24h: number }>();
198	  for (const r of real) {
199	    const key = r.source?.trim() || '(none)';
200	    const s = sourceMap.get(key) ?? { count: 0, last24h: 0 };
201	    s.count += 1;
202	    if (now - r.createdAt.getTime() < DAY_MS) s.last24h += 1;
203	    sourceMap.set(key, s);
204	  }
205	  const sources = [...sourceMap.entries()]
206	    .map(([source, s]) => ({ source, ...s }))
207	    .sort((a, b) => b.count - a.count || a.source.localeCompare(b.source));
208	
209	  // --- Companies (corporate + edu domains, grouped) -------------------------
210	  const domainGroups = new Map<string, { kind: 'corporate' | 'edu'; rows: WaitlistRow[] }>();
211	  for (const r of real) {
212	    const domain = domainOf(r.email);
213	    if (!domain) continue;
214	    const kind = classifyDomain(domain);
215	    if (kind === 'personal') continue;
216	    const g = domainGroups.get(domain) ?? { kind, rows: [] };
217	    g.rows.push(r);
218	    domainGroups.set(domain, g);
219	  }
220	  const toEntry = (r: WaitlistRow): IntelEntry => ({
221	    email: r.email,
222	    source: r.source,
223	    note: r.note?.trim() || null,
224	    createdAt: r.createdAt.toISOString(),
225	  });
226	  const companies: IntelCompany[] = [...domainGroups.entries()]
227	    .map(([domain, g]) => ({
228	      domain,
229	      kind: g.kind,
230	      count: g.rows.length,
231	      knownName: KNOWN_COMPANIES[domain] ?? null,
232	      latestAt: g.rows[0].createdAt.toISOString(), // rows already newest-first
233	      entries: g.rows.map(toEntry),
234	    }))
235	    // Team clusters first (count desc), then known orgs, then most recent.
236	    .sort(
237	      (a, b) =>
238	        b.count - a.count ||
239	        Number(Boolean(b.knownName)) - Number(Boolean(a.knownName)) ||
240	        b.latestAt.localeCompare(a.latestAt)
241	    );
242	
243	  // --- Recent feed -----------------------------------------------------------
244	  const recent: IntelRecent[] = real.slice(0, RECENT_LIMIT).map((r) => {
245	    const domain = domainOf(r.email);
246	    return {
247	      id: r.id,
248	      ...toEntry(r),
249	      domainKind: classifyDomain(domain),
250	      knownName: KNOWN_COMPANIES[domain] ?? null,
251	    };
252	  });
253	
254	  // --- Notes (all messages, newest first) -------------------------------------
255	  const notes = real.filter(hasNote).map((r) => ({
256	    ...toEntry(r),
257	    knownName: KNOWN_COMPANIES[domainOf(r.email)] ?? null,
258	  }));
259	
260	  return {
261	    generatedAt: new Date(now).toISOString(),
262	    totals: {
263	      all: real.length,
264	      lastHour: inWindow(HOUR_MS),
265	      last24h: inWindow(DAY_MS),
266	      last7d: inWindow(7 * DAY_MS),
267	      withNotes: notes.length,
268	      corporate: corporateCount,
269	      corporatePct: real.length ? Math.round((corporateCount / real.length) * 100) : 0,
270	    },
271	    trend,
272	    sources,
273	    companies,
274	    recent,
275	    notes,
276	  };
277	}
278

