/* ===============================================
   /admin — waitlist intelligence dashboard
   Uses the dashboard design tokens (dashboard.css / globals.css):
   --brand-orange, --color-bg-*, --color-text-*, --color-border-*
   =============================================== */

.aw-shell {
  min-height: 100vh;
  background: var(--color-bg-primary, #1a1916);
  color: var(--color-text-primary, #fef6ed);
  padding: 24px clamp(16px, 4vw, 48px) 64px;
  font-family: "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, sans-serif;
}

.aw-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 60vh;
  color: var(--color-text-tertiary, #8a7d6f);
  font-size: 15px;
}

/* --- header ------------------------------------ */

.aw-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}

.aw-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 26px;
  font-weight: 700;
  margin: 0;
}

.aw-live-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--success-green, #7eb663);
  box-shadow: 0 0 8px var(--success-green, #7eb663);
  animation: aw-pulse 2s ease-in-out infinite;
}

@keyframes aw-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.aw-subtitle {
  display: block;
  margin-top: 2px;
  font-size: 12px;
  color: var(--color-text-tertiary, #8a7d6f);
}

.aw-delta {
  color: var(--brand-orange, #fd6500);
  font-weight: 700;
}

.aw-refresh {
  background: var(--color-bg-tertiary, rgba(255, 255, 255, 0.08));
  color: var(--color-text-secondary, #c4b5a0);
  border: 1px solid var(--color-border-primary, rgba(255, 255, 255, 0.1));
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.aw-refresh:hover {
  border-color: var(--brand-orange, #fd6500);
  color: var(--color-text-primary, #fef6ed);
}

/* --- stat cards --------------------------------- */

.aw-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}

.aw-stat {
  background: var(--color-bg-secondary, rgba(255, 255, 255, 0.05));
  border: 1px solid var(--color-border-primary, rgba(255, 255, 255, 0.1));
  border-radius: 12px;
  padding: 16px;
}

.aw-stat-accent {
  border-color: rgba(253, 101, 0, 0.4);
  background: rgba(253, 101, 0, 0.08);
}

.aw-stat-value {
  font-size: 28px;
  font-weight: 700;
  line-height: 1.1;
}

.aw-stat-accent .aw-stat-value {
  color: var(--brand-orange, #fd6500);
}

.aw-stat-label {
  margin-top: 4px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-text-tertiary, #8a7d6f);
}

/* --- panels ------------------------------------- */

.aw-panel {
  background: var(--color-bg-secondary, rgba(255, 255, 255, 0.05));
  border: 1px solid var(--color-border-primary, rgba(255, 255, 255, 0.1));
  border-radius: 12px;
  padding: 18px;
  margin-bottom: 16px;
}

.aw-panel-title {
  margin: 0 0 14px;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text-secondary, #c4b5a0);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.aw-panel-meta {
  font-weight: 400;
  text-transform: none;
  letter-spacing: 0;
  color: var(--color-text-tertiary, #8a7d6f);
  margin-left: 8px;
  font-size: 12px;
}

.aw-columns {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 16px;
  align-items: start;
}

@media (max-width: 1100px) {
  .aw-columns {
    grid-template-columns: 1fr;
  }
}

/* --- trend chart --------------------------------- */

.aw-trend {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 90px;
}

.aw-trend-bar {
  flex: 1;
  height: 100%;
  display: flex;
  align-items: flex-end;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.03);
}

.aw-trend-fill {
  width: 100%;
  border-radius: 2px;
  background: linear-gradient(180deg, var(--brand-orange, #fd6500), rgba(253, 101, 0, 0.45));
  min-height: 0;
  transition: height 0.4s ease;
}

/* --- sources ------------------------------------- */

.aw-sources {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.aw-source-row {
  display: grid;
  grid-template-columns: 120px 1fr 70px;
  align-items: center;
  gap: 10px;
  font-size: 12px;
}

.aw-source-name {
  color: var(--color-text-secondary, #c4b5a0);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-ibm-plex-mono), monospace;
}

.aw-source-track {
  height: 8px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.05);
  overflow: hidden;
}

.aw-source-fill {
  display: block;
  height: 100%;
  border-radius: 4px;
  background: var(--brand-orange, #fd6500);
  opacity: 0.75;
}

.aw-source-count {
  text-align: right;
  color: var(--color-text-primary, #fef6ed);
  font-variant-numeric: tabular-nums;
}

.aw-source-delta {
  font-style: normal;
  color: var(--success-green, #7eb663);
  margin-left: 5px;
  font-size: 11px;
}

/* --- companies ------------------------------------ */

.aw-company-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 720px;
  overflow-y: auto;
}

.aw-company {
  border: 1px solid var(--color-border-primary, rgba(255, 255, 255, 0.08));
  border-radius: 10px;
  background: var(--color-bg-card, #1a1916);
}

.aw-company-summary {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  cursor: pointer;
  list-style: none;
  font-size: 13px;
}

.aw-company-summary::-webkit-details-marker {
  display: none;
}

.aw-company-summary:hover {
  background: var(--color-bg-card-hover, #252320);
  border-radius: 10px;
}

.aw-company-domain {
  font-family: var(--font-ibm-plex-mono), monospace;
  font-weight: 600;
  color: var(--color-text-primary, #fef6ed);
}

.aw-company-when {
  margin-left: auto;
  font-size: 11px;
  color: var(--color-text-muted, #6a5f52);
  white-space: nowrap;
}

.aw-company-entries {
  padding: 4px 12px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-top: 1px solid var(--color-border-primary, rgba(255, 255, 255, 0.06));
}

/* --- badges & chips -------------------------------- */

.aw-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 99px;
  white-space: nowrap;
}

.aw-badge-cluster {
  background: var(--brand-orange, #fd6500);
  color: #1a1208;
}

.aw-badge-known {
  background: rgba(126, 182, 99, 0.18);
  color: var(--success-green, #7eb663);
  border: 1px solid rgba(126, 182, 99, 0.35);
}

.aw-badge-corp {
  background: rgba(91, 163, 199, 0.15);
  color: var(--memory-blue, #5ba3c7);
}

.aw-badge-edu {
  background: rgba(212, 165, 116, 0.15);
  color: var(--neural-amber, #ffb366);
}

.aw-chip {
  font-size: 10px;
  padding: 2px 7px;
  border-radius: 99px;
  background: var(--color-bg-tertiary, rgba(255, 255, 255, 0.08));
  color: var(--color-text-tertiary, #8a7d6f);
  font-family: var(--font-ibm-plex-mono), monospace;
  white-space: nowrap;
}

/* --- feed / entries ---------------------------------- */

.aw-tabs {
  display: flex;
  gap: 6px;
  margin-bottom: 12px;
}

.aw-tab {
  background: transparent;
  border: 1px solid var(--color-border-primary, rgba(255, 255, 255, 0.1));
  color: var(--color-text-tertiary, #8a7d6f);
  border-radius: 8px;
  padding: 7px 14px;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.aw-tab-active {
  background: rgba(253, 101, 0, 0.12);
  border-color: rgba(253, 101, 0, 0.5);
  color: var(--color-text-primary, #fef6ed);
}

.aw-tab-count {
  margin-left: 5px;
  font-size: 11px;
  color: var(--brand-orange, #fd6500);
  font-weight: 700;
}

.aw-feed {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 860px;
  overflow-y: auto;
}

.aw-feed-row {
  padding: 9px 11px;
  border-radius: 9px;
  border: 1px solid transparent;
  background: var(--color-bg-card, #1a1916);
}

.aw-feed-corporate {
  border-color: rgba(91, 163, 199, 0.25);
}

.aw-entry-head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 12px;
}

.aw-entry-email {
  font-family: var(--font-ibm-plex-mono), monospace;
  color: var(--color-text-primary, #fef6ed);
  word-break: break-all;
}

.aw-entry-when {
  margin-left: auto;
  font-size: 11px;
  color: var(--color-text-muted, #6a5f52);
  white-space: nowrap;
}

.aw-note {
  margin-top: 6px;
  padding: 7px 10px;
  border-left: 2px solid var(--brand-orange, #fd6500);
  border-radius: 0 7px 7px 0;
  background: rgba(253, 101, 0, 0.06);
  color: var(--neural-amber, #ffb366);
  font-size: 12.5px;
  line-height: 1.45;
  white-space: pre-wrap;
  word-break: break-word;
}

.aw-empty {
  color: var(--color-text-muted, #6a5f52);
  font-size: 13px;
  padding: 16px 0;
  text-align: center;
}

